import {playerMail,mailUrl} from './mail-trigger-hooks.js';
import {createMatch, applyScore, undo, checkout} from './scoring.js';

/** The real score engine with explicit browser-local opponents and transport simulations. */
export function createRooms(ctx) {
  const {icon, esc, avatar, badge, button, header, sectionHeading, empty}=ctx;
  const setupNames={remote:'Ieder vanuit huis',localone:'Samen aan één bord',localtwo:'Twee borden op locatie',hybrid:'Club + thuis'};
  const typeNames={practice:'Oefenwedstrijd',ranked:'Competitief',league:'Competitie',tournament:'Toernooi'};
  const actors=new Map();
  let scoreText='', cameraStream=null, microphoneStream=null, mediaError='', busy=false, pairedCode='';
  const db=()=>ctx.db;
  const scope=()=>Number(ctx.scopeId?.()??db().play?.activeClubId)||null;
  const clubs=()=>db().play?.clubs?.items||[];
  const clubName=id=>clubs().find(c=>c.id===Number(id))?.name||'Club';
  const memberIds=id=>(clubs().find(c=>c.id===Number(id))?.members||[]).map(m=>Number(typeof m==='object'?m.id:m));
  const playerClubs=id=>clubs().filter(c=>memberIds(c.id).includes(Number(id))).map(c=>c.name);
  const blocked=id=>(db().play?.social?.blocked||[]).map(Number).includes(Number(id));
  const current=()=>db().matches.find(m=>m.id===Number(ctx.roomId()));
  const metaFor=m=>{init();return db().play.rooms[m.id];};
  const commit=()=>{ctx.save();ctx.render();};
  const initials=s=>s.split(/\s+/).map(w=>w[0]).slice(0,2).join('');
  const pname=id=>ctx.P(id).name;
  const name=id=>ctx.short(id);
  const notice=text=>`<div class="notice">${icon('info')}${text}</div>`;
  const action=(text,a,cls='ghost',extra='')=>button(text,a,cls,extra);
  const live=m=>m.status==='finished'?badge('Afgelopen','finished'):badge(metaFor(m).phase==='lobby'?'Wachtkamer':metaFor(m).phase==='paused'?'Gepauzeerd':'Live',metaFor(m).phase==='playing'?'live':'pending');
  const config=m=>m.legLimit?`${m.startScore} · ${m.legLimit} vaste legs · dubbel uit`:`${m.startScore} · Best of ${m.bestOf} · dubbel uit`;
  const selected=(a,b)=>a===b?'selected':'';
  function init(){
    db().play??={};db().play.rooms??={};
    if(!db().play.globalSampleSeeded){db().play.globalSampleSeeded=true;if(!db().matches.some(m=>m.id===50)){const m=createMatch({id:50,players:[1,2],startScore:501,bestOf:5,mode:'Online',board:'Globaal',remaining:[441,385]});m.clubId=null;m.matchType='practice';db().matches.push(m);}}
    const bot=db().players.find(p=>p.id===900);
    if(!bot)db().players.push({id:900,name:'Dartbot',email:'bot@dartflow.demo',status:'bot',avg:55,oneEighties:0,finish:0,played:0,won:0});
    else if(bot.email==='bot@dartrush.demo')bot.email='bot@dartflow.demo';
    for(const m of db().matches){
      if(m.clubId===undefined)m.clubId=m.id>=1&&m.id<=4?701:null;
      db().play.rooms[m.id]??={type:m.tournament?'tournament':'practice',setup:m.mode==='Online'?'remote':m.mode==='Hybride'?'hybrid':'localone',ready:[true,true],boardChecked:[true,true],cameraRequired:m.mode==='Online'||m.mode==='Hybride',actor:0,phase:m.status==='finished'?'finished':'playing',confirmations:[false,false],correction:null,chat:[],code:`DR-${String(m.id).padStart(4,'0')}`,devices:false,voice:false,transport:'connected',audit:[],botLevel:null};
      const d=db().play.rooms[m.id];
      if(!actors.has(m.id)){let saved=0;try{saved=Number(sessionStorage.getItem('dartrush-actor-'+m.id))||0;}catch{}actors.set(m.id,saved===1?1:0);}
      Object.defineProperty(d,'actor',{configurable:true,enumerable:false,get:()=>actors.get(m.id)||0,set:v=>{actors.set(m.id,v===1?1:0);try{sessionStorage.setItem('dartrush-actor-'+m.id,String(v===1?1:0));}catch{}}});
      d.clubId=m.clubId;d.audit??=[];d.chat??=[];d.confirmations??=[false,false];d.boardChecked??=[true,true];d.transport??='connected';
    }
  }
  function createGame(options={}){
    init();
    const id=Date.now()+Math.floor(Math.random()*1000);
    const opponentId=Number(options.opponentId)||2;
    if(blocked(opponentId)){ctx.toast('Deze speler staat op je blokkeerlijst. Deblokkeer eerst bij Vrienden.');return null;}
    const clubId=Object.hasOwn(options,'clubId')?(Number(options.clubId)||null):scope();
    const setup=Object.hasOwn(setupNames,options.setup)?options.setup:'remote';
    const m=createMatch({id,players:[Number(options.playerId)||1,opponentId],startScore:Number(options.startScore)||501,bestOf:Number(options.bestOf)||5,legLimit:options.legLimit?Number(options.legLimit):null,mode:setup==='remote'?'Online':setup==='hybrid'?'Hybride':'Op locatie',board:options.board||'Online'});
    if(options.tournamentId)m.tournament=Number(options.tournamentId);
    if(options.fixtureId)m.fixtureId=options.fixtureId;
    if(options.leagueId)m.leagueId=options.leagueId;
    m.matchType=opponentId===900?'practice':options.type||'practice';m.setup=setup;m.clubId=clubId;
    db().matches.push(m);
    db().play.rooms[id]={clubId,type:opponentId===900?'practice':options.type||'practice',setup,ready:[false,opponentId===900],boardChecked:[false,opponentId===900],cameraRequired:!!options.cameraRequired,actor:0,phase:'lobby',confirmations:[false,false],correction:null,chat:[],code:`DR-${id.toString(36).slice(-5).toUpperCase()}`,devices:false,voice:false,transport:'connected',audit:[],botLevel:opponentId===900?Number(options.botLevel)||55:null,fixtureId:options.fixtureId||null,leagueId:options.leagueId||null,tournamentId:options.tournamentId||null,communityRoomId:options.communityRoomId||null};
    if(opponentId!==900&&!options.communityRoomId&&!['league','tournament'].includes(m.matchType))playerMail(ctx,'challenge-invite',`match:${id}:invited`,clubId,opponentId,{actorName:pname(m.players[0]),opponentName:pname(m.players[0]),startScore:m.startScore,bestOf:m.bestOf,actionUrl:mailUrl(ctx,'match/'+id)});scoreText='';ctx.save();ctx.openMatch(id);return id;
  }
  function newMatchForm(preset={}){
    init();
    const selectedClub=scope(),ownMembers=memberIds(selectedClub);
    const eligible=db().players.filter(p=>p.status==='approved'&&p.id!==1&&!blocked(p.id));
    const own=eligible.filter(p=>ownMembers.includes(p.id));
    const opponent=Number(preset.opponentId)||own[0]?.id||eligible[0]?.id||900;
    const globalDefault=!selectedClub||!ownMembers.includes(opponent)&&opponent!==900;
    const option=p=>`<option value="${p.id}" ${selected(p.id,opponent)}>${esc(p.name)} · ${esc(playerClubs(p.id).join(' / ')||'Vrije speler')} · Ø ${p.avg.toFixed(1)}</option>`;
    const opponents=selectedClub?`<optgroup label="Leden van ${esc(clubName(selectedClub))}">${own.map(option).join('')}</optgroup><optgroup data-room-outside label="Andere spelers · kies Globaal spelen" ${globalDefault?'':'disabled'}>${eligible.filter(p=>!ownMembers.includes(p.id)).map(option).join('')}</optgroup>`:eligible.map(option).join('');
    ctx.showModal('De volgende leg begint hier.','Kies je tegenstander, wedstrijdvorm en speelopstelling.',`<form data-form="room-new">${selectedClub?`<label class="field">Waar hoort deze wedstrijd?<select name="matchClubId" id="room-match-scope"><option value="${selectedClub}" ${globalDefault?'':'selected'}>Binnen ${esc(clubName(selectedClub))}</option><option value="global" ${globalDefault?'selected':''}>Globaal spelen · ook buiten mijn vereniging</option></select></label>`:'<input type="hidden" name="matchClubId" value="global">'}<label class="field">Tegenstander<select name="opponentId">${opponents}<option value="900" ${selected(opponent,900)}>Dartbot · computertegenstander</option></select></label><div class="field-row"><label class="field">Wedstrijdvorm<select name="type"><option value="practice">Oefenwedstrijd · geen ranking</option><option value="ranked" ${selected(preset.type,'ranked')}>Competitief · demo-rating</option></select></label><label class="field">Spel<select name="startScore">${[301,501,701].map(n=>`<option value="${n}" ${selected(db().settings?.score||501,n)}>${n}</option>`).join('')}</select></label></div><label class="field">Waar spelen jullie?<select name="setup">${Object.entries(setupNames).map(([v,l])=>`<option value="${v}" ${selected(preset.setup||'remote',v)}>${l}</option>`).join('')}</select></label><div class="field-row"><label class="field">Wedstrijdduur<select name="rules"><option value="bestof">Best of legs</option><option value="fixed">Vast aantal legs · gelijkspel mogelijk</option></select></label><label class="field">Best of<select name="bestOf">${[1,3,5,7,9,11].map(n=>`<option value="${n}" ${selected(n,db().settings?.bestOf||5)}>${n} legs</option>`).join('')}</select></label></div><div class="field-row"><label class="field">Aantal bij vaste legs<select name="legLimit"><option value="4">4 legs</option><option value="6" selected>6 legs</option><option value="8">8 legs</option><option value="10">10 legs</option></select></label><label class="field">Bordcamera<select name="cameraRequired"><option value="no">Optioneel · op vertrouwen</option><option value="yes">Verplicht voor deze wedstrijd</option></select></label></div><label class="field">Niveau Dartbot<select name="botLevel">${[25,40,55,70,85].map(n=>`<option value="${n}" ${selected(n,55)}>Gemiddeld ${n} per beurt</option>`).join('')}</select></label>${notice('Wedstrijden en tegenstanders blijven in deze demo op dit apparaat. Je kunt beide perspectieven bedienen en de tegenstander simuleren.')}<div class="modal-actions">${action('Annuleren','close-modal')}<button class="btn gold" type="submit">${icon('arrow')} Naar de wachtkamer</button></div></form>`,true);
  }
  function joinForm(){ctx.showModal('Schuif aan.','Vul de wedstrijdcode van een lokale demowedstrijd in.',`<form data-form="room-join"><label class="field">Wedstrijdcode<input class="input" name="code" required maxlength="20" placeholder="Bijvoorbeeld DR-0001" autocomplete="off"></label><div class="inline-error" id="room-form-error" role="alert"></div>${notice('Een code opent de wedstrijdgegevens die in deze browser beschikbaar zijn. Echt spelen tussen twee huizen wordt later gekoppeld.')}<div class="modal-actions">${action('Annuleren','close-modal')}<button class="btn gold" type="submit">Open wedstrijd ${icon('arrow')}</button></div></form>`);}
  function lobby(){
    init();
    const active=db().matches.filter(m=>m.status!=='finished'&&(Number(m.clubId)||null)===scope()).slice().reverse();
    return header('Speelzaal',scope()?`Daag een clublid uit bij ${esc(clubName(scope()))}, of kies globaal spelen.`:'Speel met darters van alle verenigingen. Kies je speelplek en begin aan je volgende leg.',action(icon('plus')+' Wedstrijd maken','room-new','gold'))+`<div class="dr-grid dr-grid-3"><button class="panel dr-card dr-action-card" data-action="room-new">${icon('users')}<h2>Speel tegen een vriend</h2><p>Maak een kamer en deel je wedstrijdcode.</p><span class="text-link">Uitnodigen ${icon('arrow')}</span></button><button class="panel dr-card dr-action-card" data-action="room-join">${icon('target')}<h2>Ik heb een code</h2><p>Stap direct in een bestaande demowedstrijd.</p><span class="text-link">Code invoeren ${icon('arrow')}</span></button><button class="panel dr-card dr-action-card" data-action="room-find">${icon('search')}<h2>Vind mijn tegenstander</h2><p>Bekijk een passend voorstel uit de democlub.</p><span class="text-link">Zoek op niveau ${icon('arrow')}</span></button></div><div class="dr-section-gap">${sectionHeading('In de speelzaal','Nieuwe uitdaging','room-new')}<div class="dr-grid dr-grid-2">${active.map(m=>{const d=metaFor(m);return `<article class="panel dr-card"><div class="dr-inline dr-between">${live(m)}${badge(m.clubId?clubName(m.clubId):'Globaal')}</div><div class="dr-versus">${avatar(m.players[0])}<strong>${esc(name(m.players[0]))}</strong><span>vs</span><strong>${esc(name(m.players[1]))}</strong>${avatar(m.players[1])}</div><p class="dr-meta">${esc(setupNames[d.setup])} · ${config(m)}</p><div class="dr-inline dr-between"><span class="subtle-label">${d.phase==='lobby'?'Wacht op spelers':`${m.legs[0]} – ${m.legs[1]} in legs`}</span><div class="dr-inline">${action('Kijken','room-watch','ghost small',`data-id="${m.id}"`)}${action(d.phase==='lobby'?'Naar wachtkamer':'Open wedstrijd','room-open','gold small',`data-id="${m.id}"`)}</div></div></article>`;}).join('')}</div></div>${notice('De speelzaal bevat lokale voorbeeldwedstrijden. Camerabeelden van tegenstanders zijn herkenbare demoweergaven; je eigen camera kun je echt testen.')}`;
  }
  function invitation(m){const d=metaFor(m);return `<div class="dr-invite-code"><span class="subtle-label">JOUW WEDSTRIJDCODE</span><strong>${esc(d.code)}</strong>${action(icon('clipboard')+' Link kopiëren','room-copy','ghost small')}</div>`;}
  function waitingRoom(m){const d=metaFor(m),requires=d.cameraRequired,canStart=d.ready.every(Boolean)&&(!requires||d.boardChecked.every(Boolean));return header('Wedstrijd voorbereiden',`${esc(pname(m.players[0]))} vs ${esc(pname(m.players[1]))}`,action(icon('left')+' Speelzaal','nav-lobby','ghost'))+`<div class="dr-room-grid"><section class="panel dr-card"><div class="dr-inline dr-between">${badge(typeNames[d.type]||'Oefenwedstrijd')}${badge(setupNames[d.setup])}</div><h2>Jullie wedstrijd</h2><p class="dr-meta">${config(m)}</p>${invitation(m)}<div class="dr-grid dr-grid-2">${m.players.map((id,i)=>`<div class="dr-ready ${d.ready[i]?'is-ready':''}">${avatar(id,'lg')}<h3>${esc(pname(id))}</h3><p>${d.ready[i]?'Klaar om te gooien':'Nog niet klaar'}</p>${badge(d.boardChecked[i]?'Bordbeeld gecontroleerd':requires?'Bordcontrole nodig':'Camera optioneel',d.boardChecked[i]?'approved':'pending')}</div>`).join('')}</div><div class="dr-inline dr-wrap dr-section-gap">${action(icon('check')+(d.ready[0]?' Ik ben toch nog niet klaar':' Ik ben klaar'),'room-ready','gold')}${m.players[1]!==900?action('Simuleer tegenstander','room-opponent-ready','ghost'):badge('Dartbot staat klaar','approved')}</div><div class="dr-lobby-checks"><label><input type="checkbox" id="room-board-check" ${d.boardChecked[0]?'checked':''}> Ik heb het bordbeeld gecontroleerd${requires?' (verplicht)':' (optioneel)'}</label><p class="subtle-label">Het bord van de tegenstander is een demo. De controle demonstreert de gezamenlijke startafspraak.</p></div><div class="dr-inline dr-wrap"><span class="subtle-label">${esc(name(m.players[m.turn]))} begint de eerste leg.</span>${action(icon('shuffle')+' Loten wie begint','room-toss','ghost small')}</div><div class="dr-section-gap">${action('Start de wedstrijd '+icon('arrow'),'room-start','gold block',canStart?'':'disabled')}</div></section><aside class="dr-room-aside"><section class="panel dr-card"><h2>Maak je bord klaar</h2><div class="dr-camera dr-camera-small"><div class="dr-camera-placeholder"><img src="assets/dartboard.svg" alt="Dartbord als cameravoorbeeld"><span>Eigen camera · lokaal testen</span></div><video data-local-video autoplay muted playsinline ${cameraStream?'':'hidden'}></video></div><div class="dr-inline dr-wrap">${action(icon('eye')+' '+(cameraStream?'Camera stoppen':'Eigen camera testen'),cameraStream?'room-camera-off':'room-camera-on','ghost small')}${action('Tweede toestel','room-pair','ghost small')}</div>${mediaError?`<p class="inline-error">${esc(mediaError)}</p>`:''}<p class="subtle-label">Richt de camera op het hele dartbord. Beelden worden niet opgenomen of verstuurd.</p></section><section class="panel dr-card"><h2>Vriendelijk aan de oche</h2><p class="subtle-label">Wacht tot je aan de beurt bent. Noem je score vóór je de darts uit het bord haalt. Controleer een finish samen.</p></section></aside></div>`;}
  function room(spectator=false){
    init();const m=current();if(!m)return header('Deze kamer is <em>nog leeg.</em>','Deze wedstrijd bestaat niet in de lokale demogegevens.')+empty('Open de speelzaal','Maak een nieuwe wedstrijd of voer een bekende code in.','target')+action('Naar speelzaal','nav-lobby','gold');
    const d=metaFor(m);if(d.phase==='lobby'&&!spectator)return waitingRoom(m);
    const actor=d.setup==='localone'?m.turn:d.actor;
    const mayPlay=!spectator&&d.phase==='playing'&&m.status==='live'&&!d.correction&&(d.setup==='localone'||d.actor===m.turn)&&!(d.botLevel&&m.turn===1);
    const other=spectator?1:1-d.actor,local=d.actor;
    const suggest=checkout(m.remaining[m.turn]);
    const stats=m.stats.map((s,i)=>({avg:s.darts?(s.total/s.darts*3).toFixed(1):'–',darts:s.darts,oneEighties:s.oneEighties,finish:s.highestFinish||'–'}));
    return header(`${esc(name(m.players[0]))} tegen ${esc(name(m.players[1]))}`,`${config(m)} · ${setupNames[d.setup]}${spectator?' · Kijkersmodus':''}`,`<div class="dr-inline">${action(icon('left')+' Speelzaal','nav-lobby','ghost')}${!spectator?action(icon('eye')+' Kijkers','room-watch','ghost',`data-id="${m.id}"`):action('Scorebord bedienen','room-open','gold',`data-id="${m.id}"`)}</div>`)+
      `${d.phase==='paused'?`<div class="notice">${icon('wifi')}<span>${d.transport==='disconnected'?'Demo: verbinding verbroken. De stand blijft bewaard.':'De wedstrijd is gepauzeerd.'}</span>${!spectator?action(d.transport==='disconnected'?'Verbinding herstellen':'Verder spelen','room-resume','gold small'):''}</div>`:''}${d.correction?correctionNotice(m,d,spectator):''}`+
      `<div class="dr-room-grid ${spectator?'dr-spectator':''}"><div class="dr-room-stage"><section class="dr-camera"><div class="dr-camera-head"><span>${icon('eye')} Bord van ${esc(name(m.players[other]))}</span>${badge('DEMOBEELD','pending')}</div><div class="dr-camera-placeholder"><img src="assets/dartboard.svg" alt="Illustratief dartbord; geen live camerabeeld"><span>${spectator?'Kijkersweergave van de demowedstrijd':'Bordcamera tegenstander · simulatie'}</span></div><div class="dr-camera-footer">${live(m)}<span>${esc(d.code)} · ${esc(setupNames[d.setup])}</span>${badge(d.transport==='disconnected'?'Verbinding uit':'Demo verbonden',d.transport==='disconnected'?'red':'approved')}</div>${!spectator?`<div class="dr-self-preview"><video data-local-video autoplay muted playsinline ${cameraStream?'':'hidden'}></video>${!cameraStream?`${icon('eye')}<span>Eigen camera uit</span>`:''}<small>Alleen lokaal</small></div>`:''}</section><div class="dr-room-score">${m.players.map((id,i)=>`<div class="dr-player-score ${m.turn===i&&m.status==='live'?'active':''}"><div class="dr-inline">${avatar(id)}<div><strong>${esc(pname(id))}</strong><small>${m.turn===i&&m.status==='live'?'AAN DE BEURT':`${m.legs[i]} ${m.legs[i]===1?'leg':'legs'}`}</small></div></div><b>${m.remaining[i]}</b><span>${m.legs[i]} LEGS</span></div>`).join('')}</div>${m.status==='finished'?finishedPanel(m,d,spectator):`<div class="dr-room-callout"><strong>${esc(name(m.players[m.turn]))} is aan de beurt</strong><span>${suggest?`Finishsuggestie: ${esc(suggest)}`:'Speel jezelf naar de dubbel.'}</span></div>`}${!spectator?`<div class="dr-camera-toolbar dr-inline dr-wrap">${action(icon('eye')+' '+(cameraStream?'Camera uit':'Eigen camera'),cameraStream?'room-camera-off':'room-camera-on','ghost small')}${action(icon('mail')+' '+(microphoneStream?'Microfoon uit':'Microfoon testen'),'room-microphone','ghost small')}${action('Tweede toestel','room-pair','ghost small')}${action(d.voice?'Caller aan':'Caller uit','room-voice','ghost small')}${action('Uitnodigen','room-invite','ghost small')}${d.communityRoomId?action('Naar clubkamer','room-community','ghost small'):''}</div>${mediaError?`<p class="inline-error">${esc(mediaError)}</p>`:''}`:''}<section class="panel dr-card dr-section-gap"><h2>Beurt voor beurt</h2><div class="dr-turn-list">${m.visits.length?m.visits.slice().reverse().slice(0,12).map((v,i)=>`<div class="turn-row"><small>${m.visits.length-i}</small><span>${esc(name(m.players[v.playerIndex]))}${v.bust?' · Bust':v.checkout?' · Leg gewonnen':''}</span><b>${v.score}</b><span>${v.remainingAfter}</span></div>`).join(''):'<p class="subtle-label">Nieuwe beurten verschijnen hier. De beginstand kan voorbeelddata bevatten.</p>'}</div></section></div><aside class="dr-room-aside">${!spectator&&m.status!=='finished'?`<section class="panel dr-room-keypad"><div class="dr-inline dr-between"><h2>${d.setup==='localone'?'Schrijversmodus':'Jouw beurt'}</h2>${badge(d.setup==='localone'?'Gedeeld scorebord':`Perspectief ${name(m.players[d.actor])}`)}</div>${!mayPlay?`<p class="dr-meta">${d.phase==='paused'?'De score-invoer wacht tot jullie hervatten.':d.correction?'Eerst het correctieverzoek afhandelen.':d.botLevel&&m.turn===1?'Dartbot is aan de beurt.':`${esc(name(m.players[m.turn]))} is aan zet. Simuleer de beurt of wissel het perspectief.`}</p>`:''}<div class="score-input"><label>Beurtscore<input id="room-score" inputmode="numeric" pattern="[0-9]*" maxlength="3" value="${esc(scoreText)}" ${mayPlay?'':'disabled'}></label><label>Darts<select id="room-darts" aria-label="Aantal darts" ${mayPlay?'':'disabled'}><option value="3">3 darts</option><option value="2">2 darts</option><option value="1">1 dart</option></select></label></div><div class="dr-keypad keypad">${['1','2','3','4','5','6','7','8','9','back','0','ok'].map(k=>`<button type="button" data-action="room-key" data-key="${k}" ${mayPlay?'':'disabled'} class="${k==='ok'?'confirm':''}" aria-label="${k==='ok'?'Score bevestigen':k==='back'?'Laatste cijfer wissen':k}">${k==='ok'?'OK':k==='back'?icon('backspace'):k}</button>`).join('')}</div><div class="quick-scores">${[26,60,100,180].map(v=>action(v,'room-quick','ghost small',`data-value="${v}" ${mayPlay?'':'disabled'}`)).join('')}</div><div class="inline-error" id="room-score-error" role="alert"></div>${d.phase==='playing'&&!d.correction&&m.turn!==actor||d.botLevel&&m.turn===1?`<div class="dr-section-gap">${action(d.botLevel?'Laat Dartbot gooien':`Demo: laat ${esc(name(m.players[m.turn]))} gooien`,'room-demo-turn','gold block',d.phase==='playing'&&!d.correction?'':'disabled')}</div>`:''}<div class="dr-inline dr-wrap">${action(icon('undo')+' Score herstellen','room-correct','ghost small',m.history.length&&d.phase==='playing'?'':'disabled')}${action(icon('clock')+' Pauze','room-pause','ghost small',d.phase==='playing'?'':'disabled')}</div></section>`:''}<section class="panel dr-card"><h2>Wedstrijdstatistieken</h2><div class="stat-compare"><b>${esc(name(m.players[0]))}</b><span>Deze wedstrijd</span><b>${esc(name(m.players[1]))}</b></div>${[['Gemiddelde',stats[0].avg,stats[1].avg],['180’ers',stats[0].oneEighties,stats[1].oneEighties],['Hoogste finish',stats[0].finish,stats[1].finish],['Darts',stats[0].darts,stats[1].darts]].map(([l,a,b])=>`<div class="stat-compare"><b>${a}</b><span>${l}</span><b>${b}</b></div>`).join('')}</section>${!spectator?`<section class="panel dr-card"><h2>Spelersperspectief</h2><div class="dr-inline dr-wrap">${m.players.map((p,i)=>action(esc(name(p)),'room-actor',`${d.actor===i?'gold':'ghost'} small`,`data-actor="${i}" ${p===900?'disabled':''}`)).join('')}</div><p class="subtle-label">Met de demorollen kun je beide spelers testen. ${d.setup==='localone'?'Op één bord voert de schrijver beide scores in.':'Iedere speler mag alleen zijn eigen beurt invoeren.'}</p><div class="dr-inline dr-wrap">${action('Test verbindingsuitval','room-disconnect','ghost small',m.status==='live'&&d.phase!=='paused'?'':'disabled')}${action('Spelafspraken','room-rules','ghost small')}</div></section><section class="panel dr-card"><h2>Wedstrijdchat</h2><div class="dr-chat">${d.chat.length?d.chat.slice(-6).map(c=>`<p><strong>${esc(c.name)}${c.demo?' · demo':''}</strong><span>${esc(c.text)}</span></p>`).join(''):'<p class="subtle-label">Wens elkaar succes of overleg over een score. Berichten worden alleen lokaal bewaard.</p>'}</div><form data-form="room-chat" class="dr-inline"><input class="input" name="message" maxlength="200" required placeholder="Je bericht…" aria-label="Bericht aan tegenstander"><button class="btn gold small" type="submit" aria-label="Bericht versturen">${icon('arrow')}</button></form></section>`:`<section class="panel dr-card"><h2>Kijkerslinks</h2><p class="subtle-label">Dit scorebord is alleen-lezen. Het volgt de lokale demogegevens; de bordcamera is illustratief.</p>${action('OBS-overlay bekijken','room-overlay','gold block',`data-id="${m.id}"`)}${action('Kijklink kopiëren','room-copy-watch','ghost block',`data-id="${m.id}"`)}</section>`}</aside></div>${notice('De scores en spelregels werken echt op dit apparaat. Tegenstanders, cameraverbindingen en netwerkherstel worden gesimuleerd. Je eigen camera en microfoon worden alleen lokaal getest.')}`;
  }
  function correctionNotice(m,d,spectator){const mine=d.correction.actor===d.actor;return `<div class="notice"><div>${icon('undo')} <strong>Correctieverzoek</strong><br>${esc(name(m.players[d.correction.actor]))} wil terug naar de eigen laatste beurt. ${d.correction.count} beurt${d.correction.count>1?'en worden':' wordt'} teruggedraaid.</div>${!spectator?`<div class="dr-inline dr-wrap">${!mine?action('Akkoord','room-correction-accept','gold small')+action('Afwijzen','room-correction-reject','ghost small'):action('Simuleer akkoord tegenstander','room-correction-demo','ghost small')}</div>`:''}</div>`;}
  function finishedPanel(m,d,spectator){const title=m.draw?'Gelijkspel!':`${esc(pname(m.winner))} wint!`;return `<section class="panel dr-card dr-result"><div class="dr-inline">${icon('trophy')}<h2>${title}</h2></div><p>${m.legs[0]} – ${m.legs[1]} in legs · ${d.confirmations.every(Boolean)?'Door beide spelers bevestigd':'Wacht op bevestiging'}</p><div class="dr-inline dr-wrap">${m.players.map((p,i)=>badge(`${name(p)}: ${d.confirmations[i]?'bevestigd':'nog bevestigen'}`,d.confirmations[i]?'approved':'pending')).join('')}</div>${!spectator?`<div class="dr-inline dr-wrap dr-section-gap">${action('Ik bevestig de uitslag','room-confirm-result','gold',d.confirmations[d.actor]?'disabled':'')}${action('Simuleer bevestiging tegenstander','room-confirm-opponent','ghost',d.confirmations[1-d.actor]?'disabled':'')}${action('Uitslag betwisten','room-dispute','ghost',d.finalApplied?'disabled':'')}</div>${d.dispute?notice(`Uitslag betwist: ${esc(d.dispute)}. De organisator kan dit in de demo beoordelen.`):''}<div class="dr-section-gap">${action('Nog een potje? Revanche '+icon('arrow'),'room-rematch','gold')}</div>`:''}</section>`;}
  function camera(){init();return header('Camera en microfoon','Test je camera of loop de koppeling met een tweede toestel door.',action('Naar speelzaal','nav-lobby','ghost'))+`<div class="dr-grid dr-grid-2"><section class="panel dr-card"><h2>Eigen camerabeeld</h2><div class="dr-camera"><div class="dr-camera-placeholder"><img src="assets/dartboard.svg" alt="Voorbeeldopstelling van een bordcamera"><span>Camera nog niet actief</span></div><video data-local-video autoplay muted playsinline ${cameraStream?'':'hidden'}></video></div><div class="dr-inline dr-wrap dr-section-gap">${action(icon('eye')+' '+(cameraStream?'Camera stoppen':'Camera toestaan en testen'),cameraStream?'room-camera-off':'room-camera-on','gold')}${action(microphoneStream?'Microfoon stoppen':'Microfoon testen','room-microphone','ghost')}</div><div id="room-media-status" class="inline-error">${mediaError?esc(mediaError):''}</div><p class="subtle-label">Je ziet een echte lokale preview. Er wordt niets opgenomen of naar een ander toestel verstuurd.</p></section><section class="panel dr-card"><h2>Koppel aan je wedstrijd</h2><form data-form="room-camera-pair"><label class="field">Wedstrijdcode<input class="input" name="code" required maxlength="20" placeholder="DR-0001" value="${esc(pairedCode)}"></label><div id="room-form-error" class="inline-error" role="alert"></div><button class="btn gold" type="submit">Demokoppeling bevestigen ${icon('check')}</button></form>${pairedCode?`<div class="notice">${icon('check')}Demokoppeling voor ${esc(pairedCode)} is actief. Cameratransport tussen toestellen volgt in de ontwikkelfase.</div>`:''}<ol class="dr-setup-list"><li>Zet je telefoon stabiel bij het bord.</li><li>Zorg dat het hele bord en de dubbels zichtbaar zijn.</li><li>Test de camera en controleer het beeld.</li><li>Je tweede toestel blijft vrij voor de scores.</li></ol>${notice('Deze camera-demo werkt zelfstandig. Een QR of code maakt nog geen echte verbinding tussen twee apparaten.')}</section></div>`;}
  function pairingModal(){const m=current(),d=m?metaFor(m):null;ctx.showModal('Een tweede toestel als camera.','Houd je scorebord vrij en zet een telefoon bij het dartbord.',`<div class="dr-pair-layout"><img class="dr-qr" src="assets/camera-qr.svg" alt="QR-code naar de Dartflow camera-demo"><div><strong>Scan de QR-code</strong><p class="subtle-label">De QR opent de camera-demo. Vul daar de code hieronder in.</p>${d?`<div class="dr-invite-code"><strong>${esc(d.code)}</strong></div>`:''}</div></div>${notice('De QR-code opent echt de camera-demo. In deze versie worden geen beelden tussen toestellen verstuurd; het koppelen is een zichtbare simulatie.')}<div class="modal-actions">${action('Sluiten','close-modal')}${action('Open camera-demo','room-camera-page','gold')}</div>`);}
  async function copy(text,msg){try{await navigator.clipboard.writeText(text);ctx.toast(msg);}catch{ctx.showModal('Kopieer deze link.','Automatisch kopiëren is in deze browser niet beschikbaar.',`<label class="field">Link<input class="input" readonly value="${esc(text)}"></label><div class="modal-actions">${action('Sluiten','close-modal','gold')}</div>`);}}
  const url=(path)=>`${ctx.baseUrl||location.origin+location.pathname}#${path}`;
  function error(text){const el=document.getElementById('room-score-error');if(el)el.textContent=text;else ctx.toast(text);}
  function submitted(doubleConfirmed=false,dartsOverride){
    const m=current();if(!m)return;const d=metaFor(m);
    if(d.phase!=='playing'||d.correction)return error('Deze wedstrijd wacht. Hervat eerst of handel het correctieverzoek af.');
    if(d.setup!=='localone'&&d.actor!==m.turn)return error('Wacht tot je aan de beurt bent of wissel het demoperspectief.');
    if(d.botLevel&&m.turn===1)return error('Dartbot is aan de beurt.');
    const value=document.getElementById('room-score')?.value??scoreText;
    if(!/^\d{1,3}$/.test(value))return error('Voer een score van 0 tot 180 in.');
    const darts=dartsOverride??Number(document.getElementById('room-darts')?.value||3);
    const result=applyScore(m,Number(value),{darts,doubleConfirmed});
    if(result.error)return error(result.error);
    if(result.needsDouble){scoreText=value;ctx.showModal('Zit de dubbel erin?','De laatste dart van een finish moet een dubbel zijn.',`<div class="checkout"><small>Finish ${value} met ${darts} dart${darts===1?'':'s'}</small>${esc(checkout(Number(value))||'Dubbel uit')}</div><div class="modal-actions">${action('Nog niet','close-modal')}${action('Ja, dubbel geraakt','room-double','gold',`data-darts="${darts}"`)}</div>`);return;}
    accept(m,result,Number(value));
  }
  function accept(previous,result,score,isDemo=false){
    const d=metaFor(previous);const m={...result.match,fixtureId:previous.fixtureId,leagueId:previous.leagueId,tournament:previous.tournament,matchType:previous.matchType,setup:previous.setup};
    db().matches[db().matches.findIndex(x=>x.id===previous.id)]=m;
    d.audit.push({at:new Date().toISOString(),type:'score',player:previous.turn,score,demo:isDemo});
    if(m.status==='finished'){d.phase='finished';d.confirmations=[false,false];d.finalApplied=false;if(!d.botLevel)for(const pid of m.players)playerMail(ctx,'result-confirm',`match:${m.id}:pending:${m.visits.length}`,m.clubId,pid,{score:m.legs.join(' – '),opponentName:pname(m.players.find(id=>id!==pid)),actionUrl:mailUrl(ctx,'match/'+m.id)});}
    if(d.voice&&'speechSynthesis'in window){try{const u=new SpeechSynthesisUtterance(result.bust?'Geen score':result.legWon?'Game shot':String(score));u.lang='nl-NL';speechSynthesis.cancel();speechSynthesis.speak(u);}catch{}}
    scoreText='';ctx.closeModal();commit();ctx.toast(result.bust?'Bust! De resterende score blijft staan.':result.legWon?m.status==='finished'?'Wedstrijd klaar. Bevestig samen de uitslag.':'Leg gewonnen! Op naar de volgende.':`${score} genoteerd${isDemo?' · gesimuleerde beurt':''}.`);
  }
  function demoTurn(){const m=current();if(!m||m.status!=='live')return;const d=metaFor(m);if(d.phase!=='playing'||d.correction)return;const actualActor=d.setup==='localone'?m.turn:d.actor;if(!d.botLevel&&m.turn===actualActor)return ctx.toast('Voer je eigen beurt in met het toetsenbord.');const remaining=m.remaining[m.turn],level=d.botLevel||ctx.P(m.players[m.turn]).avg||55;let score, darts=3;
    const finish=checkout(remaining);if(finish&&Math.random()<Math.min(.85,level/110)){score=remaining;darts=finish.split(' · ').length;}else{const targets=[0,7,11,15,20,22,26,30,41,45,50,55,60,66,70,80,81,85,95,100,120,121,140,180];const aim=Math.max(0,level+(Math.random()-.5)*75);const candidates=targets.filter(s=>s<remaining-1&&applyScore(m,s,{darts:3,doubleConfirmed:true}).error===undefined);score=candidates.sort((a,b)=>Math.abs(a-aim)-Math.abs(b-aim))[0]??0;}
    const result=applyScore(m,score,{darts,doubleConfirmed:true});if(result.error)return ctx.toast(result.error);accept(m,result,score,true);
  }
  function setCameraStatus(msg){mediaError=msg;const el=document.getElementById('room-media-status');if(el)el.textContent=msg;}
  async function cameraOn(){if(busy)return;busy=true;mediaError='';try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Gebruik een browser met cameratoegang via HTTPS.');cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});ctx.closeModal();ctx.render();afterRender();ctx.toast('Eigen camera actief. Alleen een lokale preview.');}catch(e){setCameraStatus(e.name==='NotAllowedError'?'Cameratoegang is niet toegestaan. Je kunt de demo zonder eigen camera gebruiken.':e.name==='NotFoundError'?'Geen camera gevonden op dit apparaat.':`Camera niet beschikbaar. ${e.message||''}`);ctx.render();}finally{busy=false;}}
  function stopMedia(){cameraStream?.getTracks().forEach(t=>t.stop());microphoneStream?.getTracks().forEach(t=>t.stop());cameraStream=null;microphoneStream=null;mediaError='';}
  function afterRender(){document.querySelectorAll('video[data-local-video]').forEach(v=>{v.srcObject=cameraStream;v.hidden=!cameraStream;if(cameraStream)v.play().catch(()=>{});});}
  function correctionAccept(simulated=false){const m=current();if(!m)return;const d=metaFor(m);if(!d.correction)return;if(!simulated&&d.correction.actor===d.actor)return ctx.toast('De andere speler moet dit verzoek beoordelen.');let next=m;for(let n=0;n<d.correction.count;n++)next=undo(next);db().matches[db().matches.findIndex(x=>x.id===m.id)]={...next,tournament:m.tournament,fixtureId:m.fixtureId,leagueId:m.leagueId,matchType:m.matchType,setup:m.setup};d.audit.push({at:new Date().toISOString(),type:'correction',count:d.correction.count,simulated});d.correction=null;d.phase='playing';scoreText='';commit();ctx.toast('Correctie goedgekeurd. De betrokken beurten zijn teruggedraaid.');}
  function confirmResults(other=false){const m=current();if(!m||m.status!=='finished')return;const d=metaFor(m);if(d.dispute){ctx.toast('Een betwiste uitslag moet eerst door de organisator worden afgehandeld.');return;}d.confirmations[other?1-d.actor:d.actor]=true;if(d.confirmations.every(Boolean)&&!d.finalApplied){d.finalApplied=true;ctx.onFinished?.(m);if(!d.botLevel)for(const pid of m.players)playerMail(ctx,'result-confirmed',`match:${m.id}:confirmed:${m.visits.length}`,m.clubId,pid,{score:m.legs.join(' – '),opponentName:pname(m.players.find(id=>id!==pid)),actionUrl:mailUrl(ctx,'match/'+m.id)});}commit();ctx.toast(d.confirmations.every(Boolean)?'Uitslag definitief bevestigd.':'Bevestiging opgeslagen.');}
  function handleAction(a,b){
    if(!a.startsWith('room-'))return false;
    if(a==='room-invite-friend'){newMatchForm({opponentId:Number(b.dataset.id)||2});return true;}
    if(a==='room-find-opponent')a='room-find';
    if(a==='room-camera-test')a='room-camera-on';
    if(a==='room-copy-invite'){const target=db().matches.find(m=>m.id===Number(b.dataset.id))||current();if(target)copy(url(`match/${target.id}`),'Wedstrijdlink gekopieerd. Deze demo is lokaal.');return true;}
    const m=current(),d=m?metaFor(m):null;
    switch(a){
      case'room-community':if(d?.communityRoomId)ctx.go(`community/${d.communityRoomId}`);break;
      case'room-new':newMatchForm({opponentId:b.dataset.opponent?Number(b.dataset.opponent):undefined,setup:b.dataset.setup,type:b.dataset.type});break;
      case'room-open':ctx.openMatch(Number(b.dataset.id));break;
      case'room-join':joinForm();break;
      case'room-find':{const target=55;const found=db().players.filter(p=>p.status==='approved'&&p.id!==1&&!blocked(p.id)).sort((a,b)=>Math.abs(a.avg-target)-Math.abs(b.avg-target))[0];ctx.showModal('Een mooie tegenstander.','Een passend voorstel uit de democlub, rond een gemiddelde van 55.',`<div class="dr-ready">${avatar(found.id,'lg')}<h3>${esc(found.name)}</h3><p>Gemiddeld ${found.avg.toFixed(1)} · voorbeeldprofiel</p></div>${notice('Dit is een lokaal voorstel. Er wordt nog geen echte online wachtrij doorzocht.')}<div class="modal-actions">${action('Sluiten','close-modal')}${action('Uitdagen','room-new','gold',`data-opponent="${found.id}"`)}</div>`);break;}
      case'room-ready':if(d){d.ready[0]=!d.ready[0];const check=document.getElementById('room-board-check');if(check)d.boardChecked[0]=check.checked;commit();}break;
      case'room-opponent-ready':if(d){if(!d.ready[1]&&!d.botLevel&&!d.communityRoomId&&['practice','ranked'].includes(d.type))playerMail(ctx,'challenge-accepted',`match:${m.id}:accepted`,m.clubId,m.players[0],{actorName:pname(m.players[1]),opponentName:pname(m.players[1]),startScore:m.startScore,bestOf:m.bestOf,actionUrl:mailUrl(ctx,'match/'+m.id)});d.ready[1]=true;d.boardChecked[1]=true;d.chat.push({name:name(m.players[1]),text:'Ik ben klaar. Succes!',demo:true});commit();ctx.toast('De demotegenstander staat klaar.');}break;
      case'room-start':if(d&&d.ready.every(Boolean)&&(!d.cameraRequired||d.boardChecked.every(Boolean))){d.phase='playing';commit();ctx.toast('Game on!');}break;
      case'room-toss':if(d&&d.phase==='lobby'){m.turn=Math.random()<.5?0:1;m.legStarter=m.turn;commit();ctx.toast(`${name(m.players[m.turn])} begint.`);}break;
      case'room-key':if(d){const field=document.getElementById('room-score');if(!field||field.disabled)break;const k=b.dataset.key;if(k==='ok'){submitted();break;}scoreText=k==='back'?field.value.slice(0,-1):(field.value+k).slice(0,3);field.value=scoreText;error('');}break;
      case'room-submit':submitted();break;
      case'room-double':submitted(true,Number(b.dataset.darts));break;
      case'room-quick':{const field=document.getElementById('room-score');if(field&&!field.disabled){scoreText=b.dataset.value;field.value=scoreText;error('');}break;}
      case'room-demo-turn':demoTurn();break;
      case'room-actor':if(d){d.actor=Number(b.dataset.actor)===1?1:0;scoreText='';commit();}break;
      case'room-pause':if(d&&m.status==='live'){d.phase='paused';d.transport='connected';commit();}break;
      case'room-disconnect':if(d&&m.status==='live'){d.phase='paused';d.transport='disconnected';d.audit.push({at:new Date().toISOString(),type:'disconnect-demo'});commit();ctx.toast('Verbindingsuitval gesimuleerd. De stand blijft bewaard.');}break;
      case'room-resume':if(d&&m.status==='live'){d.phase='playing';d.transport='connected';commit();ctx.toast('Demo hervat vanaf de laatst opgeslagen beurt.');}break;
      case'room-voice':if(d){d.voice=!d.voice;commit();ctx.toast(d.voice?'Caller aan. Nieuwe scores worden uitgesproken.':'Caller uit.');}break;
      case'room-camera-on':cameraOn();break;
      case'room-camera-off':cameraStream?.getTracks().forEach(t=>t.stop());cameraStream=null;mediaError='';ctx.render();break;
      case'room-microphone':if(microphoneStream){microphoneStream.getTracks().forEach(t=>t.stop());microphoneStream=null;ctx.render();ctx.toast('Lokale microfoontest gestopt.');}else{navigator.mediaDevices?.getUserMedia({audio:true,video:false}).then(stream=>{microphoneStream=stream;ctx.render();ctx.toast('Microfoon beschikbaar. Geluid wordt niet verstuurd.');}).catch(()=>{mediaError='Microfoon niet beschikbaar of toestemming geweigerd.';ctx.render();})??ctx.toast('Microfoontest is niet beschikbaar in deze browser.');}break;
      case'room-pair':pairingModal();break;
      case'room-camera-page':ctx.closeModal();ctx.go('camera');break;
      case'room-copy':if(m)copy(url(`match/${m.id}`),'Wedstrijdlink gekopieerd. Dit is een lokale demo-uitnodiging.');break;
      case'room-copy-watch':copy(url(`spectator/${Number(b.dataset.id)||m?.id}`),'Kijklink gekopieerd. Het scorebord gebruikt lokale demogegevens.');break;
      case'room-invite':if(m)ctx.showModal('Daag je dartmaat uit.','De link opent de wedstrijd op dit apparaat.',invitation(m)+notice('Cross-device synchronisatie wordt in een volgende ontwikkelfase aangesloten. Je kunt nu beide spelers lokaal bedienen.')+`<div class="modal-actions">${action('Sluiten','close-modal','gold')}</div>`);break;
      case'room-watch':ctx.go(`spectator/${Number(b.dataset.id)||m?.id}`);break;
      case'room-overlay':ctx.go(`overlay/${Number(b.dataset.id)||m?.id}`);break;
      case'room-correct':if(d&&m.history.length&&d.phase==='playing'&&!d.correction){const actor=d.setup==='localone'?m.visits.at(-1).playerIndex:d.actor;let ix=-1;for(let i=m.visits.length-1;i>=0;i--)if(m.visits[i].playerIndex===actor){ix=i;break;}if(ix<0){ctx.toast('Je hebt nog geen eigen beurt om te herstellen.');break;}if(ix===m.visits.length-1){db().matches[db().matches.findIndex(x=>x.id===m.id)]={...undo(m),fixtureId:m.fixtureId,leagueId:m.leagueId,tournament:m.tournament,matchType:m.matchType,setup:m.setup};d.audit.push({at:new Date().toISOString(),type:'undo-own',actor});scoreText='';commit();ctx.toast('Je laatste beurt is teruggedraaid. Voer de juiste score in.');}else{d.correction={actor,count:m.visits.length-ix};commit();ctx.toast('Correctieverzoek klaar. De andere speler moet akkoord geven.');}}break;
      case'room-correction-accept':correctionAccept(false);break;
      case'room-correction-demo':correctionAccept(true);break;
      case'room-correction-reject':if(d?.correction&&d.correction.actor!==d.actor){d.audit.push({at:new Date().toISOString(),type:'correction-rejected'});d.correction=null;commit();ctx.toast('Correctieverzoek afgewezen. De stand blijft staan.');}break;
      case'room-confirm-result':confirmResults(false);break;
      case'room-confirm-opponent':confirmResults(true);break;
      case'room-rematch':if(m&&d){const options={playerId:m.players[0],opponentId:m.players[1],startScore:m.startScore,bestOf:m.bestOf,legLimit:m.legLimit,setup:d.setup,type:d.type==='practice'||d.type==='ranked'?d.type:'practice',cameraRequired:d.cameraRequired,botLevel:d.botLevel,clubId:m.clubId};ctx.closeModal();createGame(options);}break;
      case'room-dispute':if(m)ctx.showModal('Bespreek de uitslag.','Leg kort uit wat de organisator moet controleren.',`<form data-form="room-dispute"><label class="field">Toelichting<textarea class="input" name="reason" required minlength="5" maxlength="400" rows="4" placeholder="Welke score of afspraak moet worden gecontroleerd?"></textarea></label>${notice('Het geschil wordt lokaal bij deze demowedstrijd vastgelegd. Er wordt geen bericht naar een echte organisator verstuurd.')}<div class="modal-actions">${action('Annuleren','close-modal')}<button class="btn gold" type="submit">Geschil vastleggen</button></div></form>`);break;
      case'room-rules':ctx.showModal('Onze afspraken aan de oche.','Een prettige wedstrijd begint met dezelfde regels.',`<p class="subtle-label">Gooi pas als je aan de beurt bent. Een beurt heeft maximaal drie darts. Je moet precies nul bereiken met een dubbel of bull. Onder nul of één over is bust.</p><p class="subtle-label">Bij een eigen laatste beurt kun je terugdraaien. Is de tegenstander al geweest, dan is een correctieverzoek nodig. Bij cameraverlies pauzeer je samen; een korte onderbreking is geen automatisch verlies.</p><p class="subtle-label">Een camera helpt om scores te controleren, maar garandeert geen eerlijk spel. De demo neemt camerabeelden niet op.</p><div class="modal-actions">${action('Duidelijk','close-modal','gold')}</div>`);break;
    }
    return true;
  }
  function handleForm(form,f){const type=form.dataset.form;if(!type?.startsWith('room-'))return false;
    if(type==='room-new'){const chosenClub=f.matchClubId==='global'?null:Number(f.matchClubId)||null;if(chosenClub&&Number(f.opponentId)!==900&&!memberIds(chosenClub).includes(Number(f.opponentId))){ctx.toast('Kies Globaal spelen om iemand buiten deze vereniging uit te dagen.');return true;}ctx.closeModal();createGame({clubId:chosenClub,opponentId:Number(f.opponentId),startScore:Number(f.startScore),bestOf:Number(f.bestOf),legLimit:f.rules==='fixed'?Number(f.legLimit):null,type:f.type,setup:f.setup,cameraRequired:f.cameraRequired==='yes',botLevel:Number(f.botLevel)});}
    if(type==='room-join'||type==='room-camera-pair'){init();const code=f.code.trim().toUpperCase(),entry=Object.entries(db().play.rooms).find(([,d])=>d.code.toUpperCase()===code);if(!entry){const el=document.getElementById('room-form-error');if(el)el.textContent='Deze code is niet bekend in de lokale demo. Probeer DR-0001.';return true;}if(type==='room-join'){ctx.closeModal();ctx.openMatch(Number(entry[0]));ctx.toast('Demowedstrijd geopend.');}else{pairedCode=code;entry[1].devices=true;ctx.save();ctx.render();ctx.toast('Demokoppeling bewaard. Camerabeelden blijven alleen lokaal.');}}
    if(type==='room-chat'){const m=current();if(m){const d=metaFor(m),text=f.message.trim().slice(0,200);if(text){d.chat.push({name:name(m.players[d.actor]),text,demo:false});d.chat.push({name:name(m.players[1-d.actor]),text:/succes|hoi|hallo/i.test(text)?'Succes! Maak er een mooie pot van.':'Bericht ontvangen. Dit is een automatisch demoantwoord.',demo:true});commit();}}}
    if(type==='room-dispute'){const m=current();if(m){const d=metaFor(m);d.dispute=f.reason.trim().slice(0,400);d.confirmations=[false,false];d.finalApplied=false;d.audit.push({at:new Date().toISOString(),type:'dispute',reason:d.dispute});const recipients=new Set(m.players);const club=db().play.clubs?.items?.find(cl=>String(cl.id)===String(m.clubId));for(const member of club?.members||[])if(['owner','admin'].includes(member.role))recipients.add(member.id);if(!club)recipients.add(9);for(const pid of recipients)playerMail(ctx,'result-disputed',`match:${m.id}:disputed:${d.audit.length}`,m.clubId,pid,{actorName:m.players.map(pname).join(' tegen '),score:m.legs.join(' – '),opponentName:pname(m.players.find(id=>id!==pid)||m.players[0]),reason:d.dispute,actionUrl:mailUrl(ctx,'match/'+m.id)});ctx.save();ctx.closeModal();ctx.render();ctx.toast('Geschil lokaal vastgelegd voor de organisator.');}}
    return true;
  }
  function overlay(){const m=current();if(!m)return empty('Geen wedstrijd gekozen','Open een wedstrijd en kies de kijkersmodus.','target');const d=metaFor(m);return `<div class="dr-overlay-shell"><div class="dr-overlay-brand"><img src="assets/dartflow-logo.svg" alt="Dartflow"></div><div class="dr-overlay-score">${m.players.map((p,i)=>`<div><strong>${esc(pname(p))}</strong><b>${m.remaining[i]}</b><span>${m.legs[i]} legs</span></div>`).join('')}</div><div class="dr-inline dr-between"><span>${config(m)} · ${esc(d.code)}</span>${live(m)}</div></div><div class="dr-section-gap">${notice('Voorbeeld van een uitzendingsoverlay met lokale scores. Een publieke OBS-bron met externe livegegevens volgt later.')}${action('Terug naar kijkersmodus','room-watch','gold',`data-id="${m.id}"`)}${action('Overlaylink kopiëren','room-copy-overlay','ghost',`data-id="${m.id}"`)}</div>`;}
  document.addEventListener('input',e=>{if(e.target.id==='room-score'){scoreText=e.target.value.replace(/\D/g,'').slice(0,3);e.target.value=scoreText;error('');}});
  document.addEventListener('change',e=>{if(e.target.id==='room-match-scope'){const outside=document.querySelector('[data-room-outside]');if(outside)outside.disabled=e.target.value!=='global';}if(e.target.id==='room-board-check'){const m=current();if(m){metaFor(m).boardChecked[0]=e.target.checked;commit();}}});
  document.addEventListener('keydown',e=>{if(e.target.id==='room-score'&&e.key==='Enter'){e.preventDefault();submitted();}});
  // The overlay link is a read-only view of the same local state.
  const baseHandler=handleAction;
  return {init,lobby,room,camera,overlay,createGame,handleAction(a,b,e){if(a==='room-copy-overlay'){copy(url(`overlay/${Number(b.dataset.id)||current()?.id}`),'Overlaylink gekopieerd. Dit is een lokale demoweergave.');return true;}return baseHandler(a,b,e);},handleForm,afterRender,stopMedia};
}
